mapper.select:
select t.tts_name,t.tts_name ttsName,t.tts_path,t.tts_path ttsPath,t.status_cd,t.status_cd
statusCd,t.remark,t.tts_type,t.tts_type ttsType,t.community_id,t.community_id communityId,t.tt_id,t.tt_id ttId,
t.create_time createTime
from tel_tts t
where 1 =1

    and t.tts_name= #{ttsName}


    and t.tts_path= #{ttsPath}


    and t.status_cd= #{statusCd}


    and t.remark= #{remark}


    and t.tts_type= #{ttsType}


    and t.community_id= #{communityId}


    and t.tt_id= #{ttId}

order by t.create_time desc

    limit #{page}, #{row}

